package vn.sland.controller;

import jakarta.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import vn.sland.repository.AppRepository;import vn.sland.service.StorageService;import vn.sland.util.WebUtil;import java.util.*;

@Controller
public class AdminController extends BaseController {
 private final AppRepository repo;private final StorageService storage;public AdminController(AppRepository repo,StorageService storage){this.repo=repo;this.storage=storage;}private String guard(HttpSession s){return WebUtil.admin(s)?null:"redirect:/login.php";}
 @GetMapping("/admin.php")String dashboard(Model m,HttpSession s){String g=guard(s);if(g!=null)return g;base(m,s,"Admin Dashboard - SLAND");m.addAttribute("ordersCount",val("SELECT COUNT(*) n FROM orders"));m.addAttribute("productsCount",val("SELECT COUNT(*) n FROM products"));m.addAttribute("usersCount",val("SELECT COUNT(*) n FROM users WHERE role='user'"));m.addAttribute("revenue",val("SELECT COALESCE(SUM(total_money),0) n FROM orders WHERE status<>'Đã hủy'"));m.addAttribute("pending",val("SELECT COUNT(*) n FROM orders WHERE status='Chờ xử lý'"));m.addAttribute("lowStock",val("SELECT COUNT(*) n FROM products WHERE quantity<=5"));m.addAttribute("newContacts",val("SELECT COUNT(*) n FROM contacts WHERE status='new'"));m.addAttribute("recentOrders",repo.list("SELECT * FROM orders ORDER BY created_at DESC LIMIT 8"));m.addAttribute("lowProducts",repo.list("SELECT * FROM products WHERE quantity<=5 ORDER BY quantity LIMIT 5"));m.addAttribute("statusChart",repo.list("SELECT status,COUNT(*) total FROM orders GROUP BY status"));m.addAttribute("topProducts",repo.list("SELECT p.name,SUM(od.quantity) sold,SUM(od.price*od.quantity) revenue FROM order_details od JOIN products p ON p.id=od.product_id JOIN orders o ON o.id=od.order_id WHERE o.status<>'Đã hủy' GROUP BY p.id,p.name ORDER BY sold DESC LIMIT 5"));return "admin";}
 @GetMapping("/admin_products.php")String products(Model m,HttpSession s){String g=guard(s);if(g!=null)return g;base(m,s,"Quản lý sản phẩm");m.addAttribute("products",repo.list("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC"));return "admin_products";}
 @GetMapping("/admin_add_product.php")String add(Model m,HttpSession s){String g=guard(s);if(g!=null)return g;base(m,s,"Thêm sản phẩm");m.addAttribute("categories",repo.list("SELECT * FROM categories ORDER BY name"));return "admin_product_form";}
 @PostMapping("/admin_add_product.php")String addPost(@RequestParam String name,@RequestParam double price,@RequestParam(name="old_price",required=false)Double old,@RequestParam(required=false,defaultValue="")String description,@RequestParam(name="category_id")int category,@RequestParam(defaultValue="0")int quantity,@RequestParam(required=false,defaultValue="")String material,@RequestParam(required=false,defaultValue="")String dimensions,@RequestParam(required=false,defaultValue="")String warranty,@RequestParam(required=false)MultipartFile image,HttpSession s)throws Exception{String g=guard(s);if(g!=null)return g;String path=storage.saveImage(image,"products",5*1024*1024L,"sp");repo.update("INSERT INTO products(name,price,old_price,description,category_id,image_url,material,dimensions,warranty,quantity) VALUES(?,?,?,?,?,?,?,?,?,?)",name,price,old,description,category,path,material,dimensions,warranty,quantity);return "redirect:/admin_products.php";}
 @GetMapping("/admin_edit_product.php")String edit(@RequestParam int id,Model m,HttpSession s){String g=guard(s);if(g!=null)return g;base(m,s,"Sửa sản phẩm");m.addAttribute("product",repo.one("SELECT * FROM products WHERE id=?",id));m.addAttribute("categories",repo.list("SELECT * FROM categories ORDER BY name"));return "admin_product_form";}
 @PostMapping("/admin_edit_product.php")String editPost(@RequestParam int id,@RequestParam String name,@RequestParam double price,@RequestParam(name="old_price",required=false)Double old,@RequestParam(required=false,defaultValue="")String description,@RequestParam(name="category_id")int category,@RequestParam(defaultValue="0")int quantity,@RequestParam(required=false,defaultValue="")String material,@RequestParam(required=false,defaultValue="")String dimensions,@RequestParam(required=false,defaultValue="")String warranty,@RequestParam(required=false)MultipartFile image,HttpSession s)throws Exception{String g=guard(s);if(g!=null)return g;String path=storage.saveImage(image,"products",5*1024*1024L,"sp");if(path==null)repo.update("UPDATE products SET name=?,price=?,old_price=?,description=?,category_id=?,material=?,dimensions=?,warranty=?,quantity=? WHERE id=?",name,price,old,description,category,material,dimensions,warranty,quantity,id);else repo.update("UPDATE products SET name=?,price=?,old_price=?,description=?,category_id=?,image_url=?,material=?,dimensions=?,warranty=?,quantity=? WHERE id=?",name,price,old,description,category,path,material,dimensions,warranty,quantity,id);return "redirect:/admin_products.php";}
 @GetMapping("/admin_delete_product.php")String delete(@RequestParam int id,HttpSession s){String g=guard(s);if(g!=null)return g;repo.update("DELETE FROM products WHERE id=?",id);return "redirect:/admin_products.php";}
 @GetMapping("/admin_users.php")String users(Model m,HttpSession s){String g=guard(s);if(g!=null)return g;base(m,s,"Quản lý người dùng");m.addAttribute("users",repo.list("SELECT * FROM users ORDER BY id DESC"));return "admin_users";}
 @PostMapping("/admin_users.php")String usersPost(@RequestParam String action,@RequestParam int id,HttpSession s){String g=guard(s);if(g!=null)return g;if("toggle_lock".equals(action))repo.update("UPDATE users SET is_locked=IF(is_locked=1,0,1) WHERE id=? AND role<>'admin'",id);return "redirect:/admin_users.php";}
 @GetMapping("/admin_vouchers.php")String vouchers(Model m,HttpSession s){String g=guard(s);if(g!=null)return g;base(m,s,"Voucher");m.addAttribute("vouchers",repo.list("SELECT * FROM vouchers ORDER BY id DESC"));return "admin_vouchers";}
 @PostMapping("/admin_vouchers.php")String vouchersPost(@RequestParam String action,@RequestParam Map<String,String>p,HttpSession s){String g=guard(s);if(g!=null)return g;if("delete".equals(action)){repo.update("DELETE FROM vouchers WHERE id=?",Integer.parseInt(p.get("id")));}else{String code=p.getOrDefault("code","").toUpperCase(Locale.ROOT);String type=p.getOrDefault("discount_type","percent");double value=Double.parseDouble(p.getOrDefault("discount_value","0"));double min=Double.parseDouble(p.getOrDefault("min_order","0"));int max=Integer.parseInt(p.getOrDefault("max_uses","100"));String expires=p.getOrDefault("expires_at","");repo.update("INSERT INTO vouchers(code,discount_type,discount_value,min_order,max_uses,expires_at,is_active,created_at) VALUES(?,?,?,?,?,NULLIF(?,''),1,NOW())",code,type,value,min,max,expires);}return "redirect:/admin_vouchers.php";}
 @GetMapping("/admin_reviews.php")String reviews(Model m,HttpSession s){String g=guard(s);if(g!=null)return g;base(m,s,"Đánh giá");m.addAttribute("reviews",repo.list("SELECT r.*,u.username,p.name product_name FROM reviews r JOIN users u ON u.id=r.user_id LEFT JOIN products p ON p.id=r.product_id ORDER BY r.created_at DESC"));return "admin_reviews";}
 @PostMapping("/admin_reviews.php")String reviewsPost(@RequestParam String action,@RequestParam int id,HttpSession s){String g=guard(s);if(g!=null)return g;if("delete".equals(action))repo.update("DELETE FROM reviews WHERE id=?",id);return "redirect:/admin_reviews.php";}
 @GetMapping("/admin_contacts.php")String contacts(Model m,HttpSession s){String g=guard(s);if(g!=null)return g;base(m,s,"Liên hệ");m.addAttribute("contacts",repo.list("SELECT * FROM contacts ORDER BY created_at DESC"));return "admin_contacts";}
 @PostMapping("/admin_contacts.php")String contactsPost(@RequestParam int id,@RequestParam(defaultValue="read")String status,HttpSession s){String g=guard(s);if(g!=null)return g;repo.update("UPDATE contacts SET status=? WHERE id=?",status,id);return "redirect:/admin_contacts.php";}
 @GetMapping("/admin_stats.php")String stats(Model m,HttpSession s){String g=guard(s);if(g!=null)return g;base(m,s,"Thống kê");m.addAttribute("byStatus",repo.list("SELECT status,COUNT(*) n FROM orders GROUP BY status"));m.addAttribute("topProducts",repo.list("SELECT product_name,SUM(quantity) qty,SUM(price*quantity) revenue FROM order_details GROUP BY product_name ORDER BY qty DESC LIMIT 10"));m.addAttribute("daily",repo.list("SELECT DATE(created_at) day,SUM(total_money) revenue FROM orders WHERE status<>'Đã hủy' GROUP BY DATE(created_at) ORDER BY day DESC LIMIT 30"));return "admin_stats";}
 @PostMapping("/update_order_status.php")String status(@RequestParam(name="order_id")long id,@RequestParam String status,@RequestParam(required=false,defaultValue="")String note,@RequestParam(name="estimated_delivery",required=false,defaultValue="")String delivery,@RequestParam(name="delivery_note",required=false,defaultValue="")String dnote,HttpSession s){String g=guard(s);if(g!=null)return g;repo.update("UPDATE orders SET status=?,estimated_delivery=COALESCE(NULLIF(?,''),estimated_delivery),delivery_note=COALESCE(NULLIF(?,''),delivery_note) WHERE id=?",status,delivery,dnote,id);repo.update("INSERT INTO order_status_history(order_id,status,note,created_at) VALUES(?,?,?,NOW())",id,status,note);if("Đã giao".equals(status)){for(var c:repo.list("SELECT id,affiliate_id,commission_amt FROM affiliate_commissions WHERE order_id=? AND status='pending'",id)){repo.update("UPDATE affiliate_commissions SET status='confirmed' WHERE id=?",c.get("id"));repo.update("UPDATE affiliates SET balance=balance+?,total_earned=total_earned+? WHERE id=?",c.get("commission_amt"),c.get("commission_amt"),c.get("affiliate_id"));}}return "redirect:/admin.php#orders-section";}
 private Object val(String sql){var x=repo.one(sql);return x==null?0:x.get("n");}
}
